import { atom, read, update } from 'claude-code'
import type { AgentSpawnResult, EngineInterface, Hook, PluginState, Register, TurnStepChunk, TurnStepResult } from 'claude-code'

import type { ContextHealth, PhasesState, PolicyDecision, PolicyState, SpawnRoute } from '../types'
import { CALIBRATION_PATH, type LoopCeilings, parseCeilings } from './calibration'
import { type Definition, INHERITING_BUILT_INS, INSTALLED_PLUGINS_PATH } from './agents'
import { type Unread, expandHome, readDefinition } from './definitions'
import { readContext } from './measure'
import { DEFAULT_PREVIEW_CHARS, DEFAULT_THRESHOLD_CHARS, offloadOptions } from './offload'
import { type Sink, offloadBlocks } from './offloadrow'
import { emptyPhases, erred, finished, isFileReadStep, isMainImplementation, spawned, startTurn, stepPhase, stepped } from './phases'
import { crossed } from './context'
import {
  CHARS_PER_TOKEN,
  OFFLOAD_TOOLS,
  STUCK_ERRORS,
  currentEffort,
  defaultEffort,
  effortFor,
  escalate,
  group,
  pressureOf,
} from './policy'
import { type Routed, type TaskClass, mainModelFor, routeAgentModel } from './route'
import { SETTINGS_PATH, unboundKeys, unboundMessage } from './config'
import { ROUTES_PER_SESSION, SPAWNS_CAP, clipped, spawnsKey, staleSpawnKeys } from './spawns'
import { inBudget, maxParallelOption } from './concurrency'
import { type GateSink, admit, configureGate, ended, released, resetGate, started } from './gate'

const DECISIONS_CAP = 50 // source: bounds $.state size; a viewer shows the last rows only

const context = atom({ plugin: 'zetetic-autopilot', key: 'context' } as const, null as ContextHealth | null)
const policy = atom({ plugin: 'zetetic-autopilot', key: 'policy' } as const, {
  mode: 'observe',
  pressure: 'none',
  quotaPercent: 80,
  offloadThresholdChars: DEFAULT_THRESHOLD_CHARS,
  offloadPreviewChars: DEFAULT_PREVIEW_CHARS,
  decisions: [],
  charsOffloaded: 0,
  errorsInRow: 0,
} as PolicyState)

const phases = atom({ plugin: 'zetetic-autopilot', key: 'phases' } as const, emptyPhases() as PhasesState)

const spawns = atom({ plugin: 'zetetic-autopilot', key: 'spawns' } as const, [] as SpawnRoute[])

// The classifier's verdict is zetetic-genius's state (a dependency): read, never written here.
const geniusState = { plugin: 'zetetic-genius', key: 'state' } as const
type Grade = { turnId: string | null; taskClass: TaskClass; effort: 'low' | 'medium' | 'high' | 'xhigh' | 'max' }

const decide = (p: PolicyState, d: PolicyDecision, charsOffloaded = 0): PolicyState => ({
  ...p,
  decisions: [...p.decisions, d].slice(-DECISIONS_CAP),
  charsOffloaded: p.charsOffloaded + charsOffloaded,
})

// The current grade. A genius mod that is not loaded leaves the value undefined, a known state
// (no grade); a read that fails is another condition, named in a decision row (issue #6).
async function gradeOf($: EngineInterface): Promise<Grade | undefined> {
  let value: PluginState['zetetic-genius']['state'] | undefined
  try {
    value = (await $.state.get(geniusState)).value
  } catch (error) {
    await note($, 'zetetic-genius state', `unreadable: ${String(error).slice(0, 100)}`)
    return undefined
  }
  const c = value?.classified
  return c === null || c === undefined ? undefined : { turnId: c.turnId, taskClass: c.taskClass, effort: c.effort }
}

// A failed read, logged once until its reason changes: the POLICY panel shows it, routing goes on
// without what could not be read.
async function note($: EngineInterface, subject: string, reason: string): Promise<void> {
  const p = await read($, policy)
  const last = p.decisions.findLast((d) => d.kind === 'unread' && d.subject === subject)
  if (last?.to === reason) return
  const at = await $.clock.now()
  await update($, policy, (s) => decide(s, { at, kind: 'unread', subject, from: '', to: reason, applied: false }))
}

// The calibrated tool-loop rung per phase, read at start and at each new main turn: a missing file
// is no calibration; an unreadable one is a named row and no calibration.
let ceilings: LoopCeilings = {}

async function readCeilings($: EngineInterface): Promise<void> {
  try {
    const path = await expandHome($, CALIBRATION_PATH)
    ceilings = (await $.fs.exists(path)) ? parseCeilings(await $.fs.read(path)) : {}
  } catch (error) {
    ceilings = {}
    await note($, 'calibration', `unreadable: ${String(error).slice(0, 100)}`)
  }
}

// Agent definitions: what the type's file pins, or why it could not be read. A definition found, and
// a file proven absent, or no installed plugin providing the type (`absent`: the records answered
// "no such file" / "no such plugin"), are remembered for
// the session; a read that failed, or a record that could not be read, is asked again at the next
// spawn, so a transient error does not stand until /clear (issue #11). The built-ins measured to
// inherit pin nothing and have no file.
const definitions = new Map<string, Definition | Unread>()

async function definitionOf($: EngineInterface, type: string): Promise<Definition | Unread> {
  const known = definitions.get(type)
  if (known !== undefined) return known
  const found = INHERITING_BUILT_INS.includes(type) ? {} : await readDefinition($, type)
  if (!('unread' in found) || found.absent) definitions.set(type, found)
  return found
}

// The full read, with the window broken down as /context does it: at start.
async function refreshContext($: EngineInterface): Promise<void> {
  const before = await read($, context)
  const after = await readContext($, await $.session.usage({ breakdown: 'summary' }), before)
  await update($, context, () => after)
}

// The step as it went out and what came back: its phase and its advisor calls, on its loop's row, and
// whether the stuck escalation set its effort (`escalated`, counted on the run the step lands in).
async function* tracked(
  $: EngineInterface,
  sent: { turnId: string; index: number; model: string; effort?: string | number; agentId?: string },
  stream: AsyncGenerator<TurnStepChunk, TurnStepResult>,
  escalated: boolean,
): AsyncGenerator<TurnStepChunk, TurnStepResult> {
  const r = yield* stream
  const at = await $.clock.now()
  const advisorCalls = (r.serverToolUses ?? []).filter((u) => u.name === 'advisor').length
  // turn.start carries no loop id and fires for a subagent's turn too (measured 2026-10-14): main's
  // row starts again at main's own first step of a new turn instead.
  const isNewMainTurn = sent.agentId === undefined && (await read($, phases)).turnId !== sent.turnId
  if (isNewMainTurn) await update($, phases, (s) => startTurn(s, sent.turnId, sent.model, at))
  await update($, phases, (s) =>
    stepped(s, {
      loopId: sent.agentId ?? 'main',
      model: r.usage?.model ?? sent.model,
      // The effort the request ran at: the one sent, else the model's API default (policy.ts), so
      // the insights ledger never keeps an effort it cannot calibrate.
      effort: sent.effort === undefined ? defaultEffort(r.usage?.model ?? sent.model) : String(sent.effort),
      phase: stepPhase(r.toolUses, r.answer),
      fileRead: isFileReadStep(r.toolUses),
      escalated,
      advisorCalls,
      at,
    }),
  )
  return r
}

// A started subagent gets its row: the model the engine resolved, the phase its type names; and its
// route, in $.state for the viewers and in $.store (`spawns:<start>:<session>`, spawns.ts) for whoever
// reads the record after the session, so an outcome is attributed to the model that ran and the rule
// that chose it.
async function placed(
  $: EngineInterface,
  e: { subagentType: string; description: string },
  r: AgentSpawnResult,
  route: Omit<SpawnRoute, 'at' | 'agentId' | 'type' | 'ran'>,
): Promise<AgentSpawnResult> {
  if (r.deny !== undefined || r.agentId === undefined) return r
  const at = await $.clock.now()
  const id = r.agentId
  await update($, phases, (s) => spawned(s, { id, type: e.subagentType, description: e.description, model: r.model, at }))
  const record: SpawnRoute = clipped({ at, agentId: id, type: e.subagentType, ...route, ran: r.model })
  await update($, spawns, (s) => [...s, record].slice(-SPAWNS_CAP))
  await keepRoute($, record)
  return r
}

// An option key the engine does not read for this install (config.ts): a toast, and a row in the POLICY
// panel, each time a session starts, instead of the defaults running unannounced.
async function checkConfig($: EngineInterface, mode: string): Promise<void> {
  try {
    const settingsPath = await expandHome($, SETTINGS_PATH)
    if (!(await $.fs.exists(settingsPath))) return
    const settings = String(await $.fs.read(settingsPath))
    const installedPath = await expandHome($, INSTALLED_PLUGINS_PATH)
    const installed = (await $.fs.exists(installedPath)) ? String(await $.fs.read(installedPath)) : undefined
    for (const u of unboundKeys(settings, installed, $.plugin.name, $.plugin.root)) {
      const message = unboundMessage(u, mode)
      await note($, 'options not bound', message)
      $.ui.toast(message)
    }
  } catch (error) {
    await note($, 'options not checked', String(error).slice(0, 120))
  }
}

// This session's key in $.store (spawns.ts), set when the session opens; a spawn before that, or after
// a failure to open it, is kept in $.state only, and the failure is a named row.
let routesKey: string | undefined

async function openRoutes($: EngineInterface): Promise<void> {
  routesKey = undefined
  try {
    const now = await $.clock.now()
    const key = spawnsKey(now, await $.session.id())
    for (const stale of staleSpawnKeys(await $.store.keys(), now)) await $.store.delete(stale)
    routesKey = key
  } catch (error) {
    await note($, 'spawn records', `not kept across sessions: ${String(error).slice(0, 100)}`)
  }
}

async function keepRoute($: EngineInterface, record: SpawnRoute): Promise<void> {
  if (routesKey === undefined) return
  try {
    const kept = ((await $.store.get(routesKey)) ?? []) as SpawnRoute[]
    await $.store.set(routesKey, [...kept, record].slice(-ROUTES_PER_SESSION))
  } catch (error) {
    await note($, 'spawn records', `not kept across sessions: ${String(error).slice(0, 100)}`)
  }
}

const routeOf = (r: Routed, applied: boolean): Omit<SpawnRoute, 'at' | 'agentId' | 'type' | 'ran'> => ({
  requested: r.requested,
  definition: r.definition,
  decided: r.model ?? r.stands,
  reason: r.reason,
  applied,
})

const onMeasure: Hook<'session.measure'> = async ($, e, next) => {
  const before = await read($, context)
  const after = await readContext($, e, before)
  await update($, context, () => after)
  await update($, policy, (p) => ({ ...p, pressure: pressureOf(after.rateLimits, p.quotaPercent, after.band) }))
  const crossing = crossed(before, after)
  if (crossing !== undefined)
    $.ui.toast(
      `context ${crossing}: ${group(after.tokens ?? 0)} tokens, the Stop guard will ${
        crossing === 'hard' ? 'block the stop' : 'ask for a checkpoint'
      }`,
    )

  return next(e)
}

// Main: the effort ladder from the graded rung, the stuck escalation, and the model under
// quota. A subagent is left as designed. Observed, or applied under enforce. A generator, as the
// event streams.
const onStep: Hook<'turn.step'> = async function* ($, e, next) {
  const p = await read($, policy)
  const isMain = e.agentId === undefined
  const grade = isMain ? await gradeOf($) : undefined
  const g = grade !== undefined && grade.turnId === e.turnId ? grade : undefined
  const have = currentEffort(e.model, e.effort)
  if (isMain && e.index === 0) await readCeilings($)
  const phase = isMain ? (await read($, phases)).loops.find((l) => l.id === 'main')?.phase : undefined
  const loop = phase === undefined || phase === null || e.index === 0 ? undefined : ceilings[phase]
  // A subagent's requests keep the effort its definition or call pinned: the ladder is main's.
  let target = (isMain ? effortFor(e.model, e.index, e.effort, p.pressure, g?.effort, loop) : undefined) ?? have
  let kind: PolicyDecision['kind'] = 'effort'
  if (isMain && p.errorsInRow >= STUCK_ERRORS) {
    const raised = escalate(target)
    if (raised !== target) {
      target = raised
      kind = 'stuck'
    }
    await update($, policy, (s) => ({ ...s, errorsInRow: 0 }))
  }
  const model = isMain ? mainModelFor(e.model, p.pressure) : undefined
  // The escalation set this step's effort only when it is applied; that holds too when the raised effort
  // is the one the step came with (it goes out unchanged, no row), since the ladder would have sent it lower.
  const escalated = kind === 'stuck' && p.mode === 'enforce'
  if (target === have && model === undefined) return yield* tracked($, e, next(e), escalated)
  const applied = p.mode === 'enforce'
  const at = await $.clock.now()
  const who = `${isMain ? 'main' : 'agent'} step ${e.index} (${e.model})`
  if (target !== have) {
    const subject = g !== undefined && e.index === 0 ? `${who} · ${g.taskClass}` : loop !== undefined ? `${who} · ${phase} calibrated` : who
    await update($, policy, (s) => decide(s, { at, kind, subject, from: String(e.effort ?? 'default'), to: target, applied }))
  }
  if (model !== undefined && e.index === 0)
    await update($, policy, (s) =>
      decide(s, { at, kind: 'model', subject: 'main · quota pressure', from: e.model, to: model, applied }),
    )
  if (!applied) return yield* tracked($, e, next(e), escalated)
  const out = { ...e, ...(target !== have ? { effort: target } : {}), ...(model !== undefined ? { model } : {}) }
  return yield* tracked($, out, next(out), escalated)
}

// The cap's view of the mod: its rows go to the POLICY panel, an agent the engine says is gone closes its row.
const gateSink = ($: EngineInterface): GateSink => ({
  decide: async (d) => {
    await update($, policy, (s) => decide(s, d))
  },
  note: (subject, reason) => note($, subject, reason),
  gone: async (id, at) => {
    await update($, phases, (s) => finished(s, id, at))
  },
})

// Subagents: the model the call or the definition pinned stands, under any pressure; an inheriting
// type runs on the family its kind and the turn's class call for. The quota's cap on how many run at
// once comes first (admit), for the main loop's own spawns only (inBudget).
const onSpawn: Hook<'agent.spawn'> = async ($, e, next) => {
  const p = await read($, policy)
  if (!inBudget(e)) return spawnRouted($, e, next, p)
  const gate = await admit($, e, p, gateSink($))
  if (gate.deny !== undefined) return { deny: gate.deny }
  try {
    const r = await spawnRouted($, e, next, p)
    if (r.deny === undefined && r.agentId !== undefined) started(r.agentId)
    return r
  } finally {
    released(gate.held)
  }
}

async function spawnRouted(
  $: EngineInterface,
  e: Parameters<Hook<'agent.spawn'>>[1],
  next: Parameters<Hook<'agent.spawn'>>[2],
  p: PolicyState,
): Promise<AgentSpawnResult> {
  // The grade counts only for the main turn it was bound to: a later turn nobody graded (a slash
  // command, a notification) routes without one, as turn.step does.
  const grade = e.parentAgentId === undefined ? await gradeOf($) : undefined
  const mainTurn = (await read($, phases)).turnId
  const cls = grade !== undefined && grade.turnId !== null && grade.turnId === mainTurn ? grade.taskClass : undefined
  // Read whatever the call says: the record names the definition's model beside the call's. A fork has no
  // definition: it runs as its parent, and the engine ignores a rewrite of its model or of a workflow agent's
  // content (AgentSpawnInput.model, .workflow), so neither is sent one.
  const rewritable = !e.fork && e.workflow === undefined
  const found = e.fork ? {} : await definitionOf($, e.subagentType)
  if ('unread' in found && e.model === undefined) await note($, `${e.subagentType} definition`, found.unread)
  const definition = 'unread' in found ? undefined : found
  const routed = routeAgentModel(e.subagentType, e.model, definition, e.parentModel, cls)
  const applied = p.mode === 'enforce' && routed.model !== undefined && rewritable
  if (routed.model !== undefined) {
    const d: PolicyDecision = {
      at: await $.clock.now(),
      kind: 'model',
      subject: `${e.subagentType}${cls === undefined ? '' : ` · ${cls}`}`,
      from: e.model ?? definition?.model ?? `inherit ${e.parentModel}`,
      to: routed.model,
      applied,
      reason: `inheriting ${e.subagentType} routed to ${routed.model} by its kind${cls === undefined ? '' : ` on a ${cls} turn`}`,
    }
    await update($, policy, (s) => decide(s, d))
  }
  return placed($, e, await next(applied ? { ...e, model: routed.model } : e), routeOf(routed, applied))
}

// The turns main was last told in, each once a turn and not once a call: the user (a toast) and the model (a
// reminder in the call's result). Reset with the session. The model's is given back when its call was refused,
// so the next call of the turn carries it; the user's is not (a toast says what main did, and the refusal
// is on the screen already).
let toastedTurn: string | null | undefined
let remindedTurn: string | null | undefined

// What the model reads after the result of its first implementing call of a turn (the engine's declarations:
// a tool.call result's `context` is "what the model reads after the tool's result and the user never sees").
// It is the instruction; the user is told the fact in a toast and never this.
const DELEGATE_REMINDER =
  'zetetic-autopilot, owner rule 2026-10-15: implementation belongs to a subagent. This session\'s main loop just ran a ' +
  'tool that changes files or state; delegate implementation to a subagent (Agent tool) and keep this loop for orchestration.'

// Owner rule, 2026-10-15: no task runs in the global session, all is delegated. A call of the main loop
// that writes code or changes things is the work a subagent is for: a row each time, a toast to the user and a
// reminder to the model once a turn. It warns and never blocks: the call goes ahead. Answers whether the model
// is owed its reminder on this call's result, and for which turn.
async function nudgeMain($: EngineInterface, e: { tool: string }): Promise<{ turnId: string | null; remind: boolean }> {
  const turnId = (await read($, phases)).turnId
  const at = await $.clock.now()
  await update($, policy, (s) =>
    decide(s, { at, kind: 'work', subject: `main · ${e.tool}`, from: 'main loop', to: 'delegate to a subagent', applied: false }),
  )
  if (toastedTurn !== turnId) {
    toastedTurn = turnId
    $.ui.toast(`main ran ${e.tool} (owner rule 2026-10-15: implementation is a subagent's work)`)
  }
  const remind = remindedTurn !== turnId
  if (remind) remindedTurn = turnId

  return { turnId, remind }
}

// The stuck signal: main's tool errors in a row, read by the next turn.step.
const onToolCall: Hook<'tool.call'> = async ($, e, next) => {
  const agentId = (e as { agentId?: string }).agentId
  const nudge = agentId === undefined && isMainImplementation(e.tool, e) ? await nudgeMain($, e) : undefined
  const ran = await next(e)
  const isBlocked = ran.deny !== undefined || ran.isError === true
  if (agentId === undefined) await update($, policy, (s) => ({ ...s, errorsInRow: isBlocked ? s.errorsInRow + 1 : 0 }))
  if (isBlocked) await update($, phases, (s) => erred(s, agentId ?? 'main'))
  if (nudge?.remind !== true) return ran
  // A refused call has no `context` to carry it: the reminder is still owed to the turn's next call.
  if (ran.deny !== undefined) {
    if (remindedTurn === nudge.turnId) remindedTurn = undefined
    return ran
  }

  // The result as core made it, whole (`ref` names its messages), with the reminder added to its context.
  return { ...ran, context: [...(ran.context ?? []), DELEGATE_REMINDER] }
}

// Memory offload (offload.ts, offloadrow.ts): a stream tool's result past the threshold is written whole to a
// file in the session's tool-results directory, which comes from the transcript path every classic SessionStart
// carries; the engine's retention sweeps it (`cleanupPeriodDays`, 30 days by default) and this mod deletes
// nothing. The stored row carries a preview, the path and the size; a result that cannot be written stays
// whole, and a row says why.
let transcriptPath: string | undefined

const onAppend: Hook<'session.append'> = async ($, e, next) => {
  const tool = e.origin.kind === 'tool' ? e.origin.tool : undefined
  if (tool === undefined || !OFFLOAD_TOOLS.has(tool)) return next(e)
  const p = await read($, policy)
  const sink: Sink = {
    note: (subject, reason) => note($, subject, reason),
    offloaded: async (plan, applied) => {
      const kept = plan.chars - plan.message.length
      const d: PolicyDecision = {
        at: await $.clock.now(),
        kind: 'offload',
        subject: tool,
        from: `${group(plan.chars)} chars`,
        to: `${plan.files[0]?.path} · about ${group(Math.round(kept / CHARS_PER_TOKEN))} tokens kept out of context`,
        applied,
      }
      await update($, policy, (s) => decide(s, d, applied ? kept : 0))
    },
  }
  const options = { thresholdChars: p.offloadThresholdChars, previewChars: p.offloadPreviewChars }
  const content = await offloadBlocks($, e.uuid, tool, e.message.content, { options, enforce: p.mode === 'enforce', transcriptPath, sink })

  return next(content === undefined ? e : { ...e, message: { ...e.message, content } })
}

// The stuck counter is a turn's own; main's ends with its turn.
const onComplete: Hook<'turn.complete'> = async ($, e, next) => {
  if (e.agentId === undefined) await update($, policy, (s) => ({ ...s, errorsInRow: 0 }))
  else ended(e.agentId)
  const at = await $.clock.now()
  await update($, phases, (s) => finished(s, e.agentId ?? 'main', at))

  return next(e)
}

// What a session starts from: no definition, phase or route known, this session's store key, the options
// checked, the configured fields set afresh (a hot reload keeps $.state from the previous load).
async function begin($: EngineInterface, mode: PolicyState['mode'], configured: (p: PolicyState) => PolicyState, capProblem?: string): Promise<void> {
  definitions.clear()
  resetGate()
  toastedTurn = undefined
  remindedTurn = undefined
  await update($, phases, () => emptyPhases())
  await update($, spawns, () => [])
  await openRoutes($)
  await checkConfig($, mode)
  await update($, policy, configured)
  if (capProblem !== undefined) await note($, 'agent cap option', capProblem)
  await refreshContext($)
}

export const register: Register = (on, options) => {
  const mode: PolicyState['mode'] = options.policy_mode === 'enforce' ? 'enforce' : 'observe'
  const quotaPercent = Number(options.quota_pressure_percent ?? 80)
  const offload = offloadOptions(options.offload_threshold_chars, options.offload_preview_chars)
  const cap = maxParallelOption(options.max_parallel_agents)
  configureGate(cap.max)
  // A hot reload keeps $.state from the previous load: the configured fields are set afresh.
  const configured = (p: PolicyState): PolicyState => ({
    ...p,
    mode,
    quotaPercent,
    offloadThresholdChars: offload.options.thresholdChars,
    offloadPreviewChars: offload.options.previewChars,
  })

  on('session.start', async ($, e, next) => {
    await begin($, mode, configured, cap.problem)

    return next(e)
  })

  // /clear, /resume and /branch reset $.state and never fire session.start again.
  on('classic.SessionStart', { source: ['clear', 'resume', 'fork'] }, async ($, e, next) => {
    await begin($, mode, configured, cap.problem)

    return next(e)
  })

  // Every start, /clear, /resume and /branch included: the transcript names the tool-results directory.
  on('classic.SessionStart', async ($, e, next) => {
    transcriptPath = e.transcript_path
    for (const problem of offload.problems) await note($, 'offload option', problem)

    return next(e)
  })

  on('session.measure', onMeasure)
  on('turn.step', onStep)
  on('agent.spawn', onSpawn)
  on('tool.call', onToolCall)
  on('session.append', { door: 'tool-result' }, onAppend)
  on('turn.complete', onComplete)
}

files.hooks/calibration.ts:
// The per-phase tool-loop effort the insights mod calibrated from its ledger, read from the file it
// writes (a mod never reads another's store; the insights mod depends on this one, not the reverse).

import type { Phase } from '../types'
import type { Effort } from './policy'

// source: zetetic-insights hooks/learn.ts CALIBRATION_PATH, the file it writes.
export const CALIBRATION_PATH = '~/.claude/zetetic-insights/calibration.json'

export type LoopCeilings = Partial<Record<Phase, Effort>>

const LEVELS: readonly string[] = ['low', 'medium', 'high']

// Version 1, a `phases` object of low/medium/high; anything else is refused with the reason.
export const parseCeilings = (text: string): LoopCeilings => {
  const raw = JSON.parse(text) as { version?: unknown; phases?: Record<string, unknown> }
  if (raw.version !== 1 || typeof raw.phases !== 'object' || raw.phases === null)
    throw new Error('calibration.json is not version 1 with a phases object')
  const bad = Object.entries(raw.phases).find(([, e]) => typeof e !== 'string' || !LEVELS.includes(e))
  if (bad !== undefined) throw new Error(`calibration.json: ${bad[0]} has effort ${String(bad[1])}, not low, medium or high`)
  return raw.phases as LoopCeilings
}

files.hooks/agents.ts:
// Pure side of an agent type's definition: where its file is and which model and effort its
// frontmatter pins. `agent.spawn` carries the Agent call's `model` only, never the definition's
// (measured 2026-10-14: memory-writer, defined haiku, spawned with `model` undefined and resolved
// to claude-haiku-5-5 below the hook), so the router reads the file itself.

// source: ~/.claude/plugins/installed_plugins.json, the engine's record of installed plugins;
// `plugins["<name>@<marketplace>"][0].installPath` is the folder a session runs.
export const INSTALLED_PLUGINS_PATH = '~/.claude/plugins/installed_plugins.json'

// source: measured 2026-10-14 with a probe mod (agent.spawn result, turn.step): Explore, Plan and
// general-purpose spawned with no `model` from an opus parent resolved to the parent's model.
export const INHERITING_BUILT_INS: readonly string[] = ['Explore', 'Plan', 'general-purpose']

export type Definition = { model?: string; effort?: string }

// The folders from `dir` up to the filesystem root, nearest first; `/` and `\\` both separate.
export const ancestors = (dir: string): string[] => {
  const out: string[] = []
  let current = dir.length > 1 ? dir.replace(/[\\/]+$/, '') : dir
  for (;;) {
    out.push(current)
    const cut = Math.max(current.lastIndexOf('/'), current.lastIndexOf('\\'))
    if (cut < 0) return out
    if (cut === 0) return current === '/' ? out : [...out, '/']
    current = current.slice(0, cut)
  }
}

type Install = { scope?: unknown; projectPath?: unknown; installPath?: unknown }

// source: Claude Code's settings precedence (local over project over user), applied to the scopes
// `installed_plugins.json` records (`scope`: user, project, local; `projectPath` for the last two,
// measured 2026-10-14 on ~/.claude/plugins/installed_plugins.json). The engine's own choice among
// several entries is not documented in the mods reference: this order is the assumption (issue #11).
const USER = 2
const SCOPE_RANK: Record<string, number> = { local: 0, project: 1, user: USER }
const norm = (p: string): string => p.replace(/\\/g, '/').replace(/\/+$/, '')

// The install path a session in `cwd` runs: among the entries whose scope covers the session (user
// entries always, project and local ones when their `projectPath` is `cwd` or a folder above it) the
// narrowest scope, then the first listed. An entry with no scope is the user's.
export const activeInstallPath = (installs: readonly Install[], cwd: string): string | undefined => {
  const here = new Set(ancestors(cwd).map(norm))
  const covering: { path: string; rank: number }[] = []
  for (const i of installs) {
    if (typeof i.installPath !== 'string' || i.installPath === '') continue
    const rank = typeof i.scope === 'string' ? (SCOPE_RANK[i.scope] ?? USER) : USER
    if (rank !== USER && !(typeof i.projectPath === 'string' && here.has(norm(i.projectPath)))) continue
    covering.push({ path: i.installPath, rank })
  }
  // Array.prototype.sort is stable: equal ranks keep their listed order.
  return covering.sort((x, y) => x.rank - y.rank)[0]?.path
}

// The files that may define a type, in the engine's precedence: a plugin's `agents/<name>.md`
// for `<plugin>:<name>` (`agents/<sub>/<name>.md` for `<plugin>:<sub>:<name>`) from the install
// that runs in `cwd`, else the project's `.claude/agents/` in each of `projectDirs` (the folders from
// the working directory up to the repository root, nearest first), then the user's (`claudeDir`, the
// engine's config directory: `~/.claude` or CLAUDE_CONFIG_DIR).
export const definitionPaths = (
  type: string,
  installedPluginsJson: string | undefined,
  claudeDir: string,
  cwd: string,
  projectDirs: readonly string[],
): string[] => {
  const colon = type.indexOf(':')
  if (colon < 0) return [...projectDirs.map((dir) => `${dir}/.claude/agents/${type}.md`), `${claudeDir}/agents/${type}.md`]
  const plugin = type.slice(0, colon)
  // `<plugin>:<sub>:<name>` is the plugin's agents/<sub>/<name>.md.
  const name = type.slice(colon + 1).split(':').join('/')
  if (installedPluginsJson === undefined) return []
  let parsed: { plugins?: Record<string, Install[]> }
  try {
    parsed = JSON.parse(installedPluginsJson) as typeof parsed
  } catch (error) {
    // A record that is not JSON is not "plugin not installed": the caller is told which it is.
    throw new Error(`installed_plugins.json is not valid JSON (${error instanceof Error ? error.message : String(error)})`.slice(0, 160))
  }
  return Object.entries(parsed.plugins ?? {})
    .filter(([key]) => key.startsWith(`${plugin}@`))
    .map(([, installs]) => activeInstallPath(installs, cwd))
    .filter((p): p is string => p !== undefined)
    .map((root) => `${root}/agents/${name}.md`)
}

// The `model:` and `effort:` lines of the leading `---` block; a file without one pins nothing.
export const parseDefinition = (md: string): Definition => {
  const block = /^---\r?\n([\s\S]*?)\r?\n---/.exec(md)
  if (block === null) return {}
  const field = (name: string): string | undefined => {
    const m = new RegExp(`^${name}:[ \\t]*["']?([^"'\\s#]+)`, 'm').exec(block[1] ?? '')
    return m?.[1]
  }
  const model = field('model')
  const effort = field('effort')
  return { ...(model === undefined ? {} : { model }), ...(effort === undefined ? {} : { effort }) }
}

// The model a definition pins; `inherit` and an absent line both leave it to the parent.
export const pinnedModel = (d: Definition): string | undefined =>
  d.model === undefined || d.model === 'inherit' ? undefined : d.model

files.hooks/definitions.ts:
// Reading agent definitions off the machine: where a `~/` path lands, and the definition file a subagent type
// names (agents.ts holds the pure side). The engine's `$` is passed in; nothing here keeps state.

import type { EngineInterface } from 'claude-code'

import { type Definition, INSTALLED_PLUGINS_PATH, ancestors, definitionPaths, parseDefinition } from './agents'
import { placePath } from './paths'

export type Unread = { unread: string; absent: boolean }

// Where a `~/` path lands on this machine: HOME, else USERPROFILE, and CLAUDE_CONFIG_DIR for what lives
// in the engine's config directory (paths.ts). No home to place it is an error with that reason.
export async function expandHome($: EngineInterface, path: string): Promise<string> {
  if (!path.startsWith('~/')) return path
  const placed = placePath(
    { home: await $.env.get('HOME'), userProfile: await $.env.get('USERPROFILE'), configDir: await $.env.get('CLAUDE_CONFIG_DIR') },
    path,
  )
  if ('reason' in placed) throw new Error(placed.reason)

  return placed.path
}

// The folders whose `.claude/agents/` may hold a project agent: the working directory and each
// folder above it up to the repository root (the first with a `.git`), so a session started in a
// subdirectory finds the project's agents. No repository above: the working directory alone.
async function projectDirs($: EngineInterface, cwd: string): Promise<string[]> {
  const chain = ancestors(cwd)
  for (const [i, dir] of chain.entries()) if (await $.fs.exists(`${dir}/.git`)) return chain.slice(0, i + 1)
  return [cwd]
}

export async function readDefinition($: EngineInterface, type: string): Promise<Definition | Unread> {
  try {
    const claudeDir = (await expandHome($, '~/.claude')).replace(/\/$/, '')
    const installed = type.includes(':') ? await $.fs.read(await expandHome($, INSTALLED_PLUGINS_PATH)) : undefined
    const cwd = await $.session.cwd()
    const paths = definitionPaths(type, installed, claudeDir, cwd, type.includes(':') ? [] : await projectDirs($, cwd))
    for (const path of paths) {
      // A file that exists and cannot be read throws: it is not "no such file".
      if (await $.fs.exists(path)) return parseDefinition(String(await $.fs.read(path)))
    }
    return paths.length === 0
      ? { unread: 'no installed plugin provides it', absent: true }
      : { unread: `no file at ${paths.join(', ')}`, absent: true }
  } catch (error) {
    return { unread: String(error).slice(0, 120), absent: false }
  }
}

files.hooks/measure.ts:
// The context window as the engine measures it, with the Stop guard's checkpoint thresholds beside it.

import type { EngineInterface } from 'claude-code'

import type { ContextHealth } from '../types'
import { THRESHOLDS_PATH, band, matchThresholds, serversOf } from './context'
import { expandHome } from './definitions'

export type Measured = {
  context: {
    tokens?: number
    window: number
    percent?: number
    breakdown?: {
      categories: readonly { name: string; tokens: number }[]
      mcpTools: readonly { serverName: string; tokens: number }[]
    }
  }
  rateLimits: readonly { kind: string; percentUsed: number }[]
  cost?: { usd: number }
}

// A measure carries no breakdown; the one read before is kept until the next full read.
export async function readContext($: EngineInterface, m: Measured, before: ContextHealth | null): Promise<ContextHealth> {
  const model = await $.session.model()
  let warn: number | null = null
  let hard: number | null = null
  let source = THRESHOLDS_PATH
  try {
    const t = matchThresholds(await $.fs.read(await expandHome($, THRESHOLDS_PATH)), model)
    if (t !== undefined) {
      warn = t.warn
      hard = t.hard
    } else source = `${THRESHOLDS_PATH} has no match for ${model}`
  } catch (error) {
    // The file is the Stop guard's. A refusal, a missing file and a file that is not JSON all leave
    // no thresholds; the viewer is told which, with the reason, instead of reading all three as absent.
    source = `${THRESHOLDS_PATH} unreadable: ${(error instanceof Error ? error.message : String(error)).slice(0, 100)}`
  }
  const reading = { tokens: m.context.tokens ?? null, warn, hard }
  return {
    ...reading,
    window: m.context.window,
    percent: m.context.percent ?? null,
    model,
    thresholdsSource: source,
    rateLimits: m.rateLimits.map((r) => ({ kind: r.kind, percentUsed: r.percentUsed })),
    usd: m.cost?.usd ?? null,
    categories:
      m.context.breakdown?.categories.map((c) => ({ name: c.name, tokens: c.tokens })) ?? before?.categories ?? [],
    mcpServers: m.context.breakdown === undefined ? (before?.mcpServers ?? []) : serversOf(m.context.breakdown.mcpTools),
    band: band(reading),
    readAt: await $.clock.now(),
  }
}

files.hooks/offload.ts:
// Lossless offload: a stream tool's result past the threshold is written whole to a file in the
// session's own tool-results directory, and the model reads a preview, the path, the size and an
// instruction to Read or grep the file. The threshold and the preview bound what enters the
// context; they never bound what is kept. Pure: the plan says what to write and what to show, the
// register file does the writing.

// source: Claude Code 2.1.300 persists a tool result past `ise(name, maxResultSizeChars, ceiling)`
// itself: Bash 30000 (`bashOutputMaxChars` default), Grep 20000, Glob and WebSearch 50000 (their
// 100000 is capped by the 50000 ceiling), WebFetch 50000 (read in the binary's strings, 2026-10-15;
// docs: code.claude.com tools-reference). 30000 is the native Bash default, so a result the engine
// already keeps (Grep past 20000, Bash past 30000) is never wrapped twice and Glob, WebFetch and
// WebSearch gain the 30000..50000 band the engine leaves inline.
export const DEFAULT_THRESHOLD_CHARS = 30000
// source: the preview the engine leaves in context for a result it persisted (`oxe = 2000`).
export const DEFAULT_PREVIEW_CHARS = 2000

// source: the engine's file API rejects a write over 4 MiB (index.d.ts, `$.fs`); a UTF-16 code unit
// is at most 3 UTF-8 bytes and a surrogate pair 4, so 1 000 000 units are at most 4 000 000 bytes.
export const PART_CHARS = 1_000_000

// The engine's own pointers to what it already keeps (`<persisted-output>`) or could not keep
// (`<truncated-output>`): a result that starts with one is not wrapped again.
const NATIVE_MARKERS = ['<persisted-output>', '<truncated-output>']
const MARKER = 'zetetic-autopilot-offload'

export type OffloadOptions = { thresholdChars: number; previewChars: number }

export type OffloadFile = { path: string; text: string }
export type OffloadPlan = { files: OffloadFile[]; message: string; chars: number; lines: number }

const isCount = (v: unknown): v is number => typeof v === 'number' && Number.isInteger(v) && v > 0

// The options as the user set them, each checked: a value that is not a positive whole number is
// named, and the default stands in its place. Left unchecked, NaN would make every result "past"
// the threshold.
export const offloadOptions = (
  threshold: unknown,
  preview: unknown,
): { options: OffloadOptions; problems: string[] } => {
  const problems: string[] = []
  const pick = (name: string, value: unknown, fallback: number): number => {
    if (value === undefined) return fallback
    if (isCount(value)) return value
    problems.push(`${name}=${JSON.stringify(value)} is not a positive whole number; using ${fallback}`)
    return fallback
  }
  const thresholdChars = pick('offload_threshold_chars', threshold, DEFAULT_THRESHOLD_CHARS)
  const asked = pick('offload_preview_chars', preview, DEFAULT_PREVIEW_CHARS)
  // A preview as long as the result would only add the pointer's lines to it.
  const previewChars = Math.min(asked, thresholdChars)
  if (previewChars < asked) problems.push(`offload_preview_chars=${asked} is past the threshold; using ${previewChars}`)
  return { options: { thresholdChars, previewChars }, problems }
}

// The directory the engine keeps this session's tool results in: the transcript
// `<projects>/<project>/<session>.jsonl` names it `<projects>/<project>/<session>/tool-results`.
// Undefined when the path is not that of the session `sessionId` (a /clear or a resume moved on).
export const toolResultsDir = (transcriptPath: string | undefined, sessionId: string): string | undefined => {
  if (transcriptPath === undefined || !transcriptPath.endsWith('.jsonl')) return undefined
  const stem = transcriptPath.slice(0, -'.jsonl'.length)
  const sep = stem.includes('/') || !stem.includes('\\') ? '/' : '\\'
  const segments = stem.split(sep)
  // The last segment must BE the session id, and no segment may climb out of the directory.
  if (segments.includes('..') || segments[segments.length - 1] !== sessionId) return undefined
  return `${stem}${sep}tool-results`
}

// A tool_use id is `toolu_...` or `call_...`; anything else a file name could not carry is replaced.
const fileSafe = (id: string): string => id.replace(/[^A-Za-z0-9_-]/g, '_')

// Splits at PART_CHARS, never between the two halves of a surrogate pair; the parts joined are the text.
export const parts = (text: string): string[] => {
  const out: string[] = []
  let at = 0
  while (at < text.length) {
    let end = Math.min(at + PART_CHARS, text.length)
    const last = text.charCodeAt(end - 1)
    if (end < text.length && last >= 0xd800 && last <= 0xdbff) end -= 1
    out.push(text.slice(at, end))
    at = end
  }
  return out
}

// The start of the text to show: up to `limit` characters, cut at a line break when one falls in the
// second half (the engine's own rule for its preview), never inside a surrogate pair.
export const previewOf = (text: string, limit: number): string => {
  let end = Math.min(limit, text.length)
  const last = text.charCodeAt(end - 1)
  if (end < text.length && last >= 0xd800 && last <= 0xdbff) end -= 1
  const head = text.slice(0, end)
  if (end === text.length) return head
  const lineEnd = head.lastIndexOf('\n')
  return lineEnd > end / 2 ? head.slice(0, lineEnd) : head
}

const count = (n: number): string => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ' ')

// pre:  `dir` is the session's tool-results directory, `toolUseId` the block's id, `joined` says the
//       text is several text blocks joined by a newline.
// post: undefined when the text is within the threshold or is one of the engine's own pointers;
//       otherwise `files` hold the text exactly (their texts joined are `text`, byte for byte) and
//       `message` is the preview, the path or paths, the size in characters and lines, and the
//       instruction to read the file. Nothing in it is a cut of the text except the preview, which
//       is named as the start.
export const planOffload = (
  text: string,
  toolUseId: string,
  dir: string,
  options: OffloadOptions,
  joined = false,
): OffloadPlan | undefined => {
  if (text.length <= options.thresholdChars) return undefined
  if (NATIVE_MARKERS.some((m) => text.startsWith(m))) return undefined
  const sep = dir.includes('/') || !dir.includes('\\') ? '/' : '\\'
  const pieces = parts(text)
  const name = `autopilot-${fileSafe(toolUseId)}`
  const files = pieces.map((piece, i) => ({
    path: `${dir}${sep}${name}${pieces.length === 1 ? '' : `.${i + 1}`}.txt`,
    text: piece,
  }))
  const lines = text.split('\n').length
  const where =
    files.length === 1
      ? `Full output saved to: ${files[0]?.path}`
      : `Full output saved in ${files.length} files of at most ${count(PART_CHARS)} characters, to be read in order:\n${files.map((f) => f.path).join('\n')}`
  const preview = previewOf(text, options.previewChars)
  const message = [
    `<${MARKER}>`,
    `Output too large (${count(text.length)} characters, ${count(lines)} lines). ${where}`,
    ...(joined ? ['The file holds the result\'s text blocks joined by a newline.'] : []),
    `Preview (the first ${count(preview.length)} characters):`,
    preview,
    'Nothing was removed: Read or grep the file for the rest.',
    `</${MARKER}>`,
  ].join('\n')

  return { files, message, chars: text.length, lines }
}

files.hooks/offloadrow.ts:
// The offload as the engine sees it: the blocks of one stored tool-result row, the files written for
// the long ones, the blocks the model will read. The plan itself is offload.ts (pure); this is the
// part that writes and reports, with the policy state and the cockpit rows behind a `Sink`.
import type { EngineInterface } from 'claude-code'

import { type OffloadOptions, type OffloadPlan, planOffload, toolResultsDir } from './offload'
import { resultText } from './policy'

export type Block = { type: string; tool_use_id?: unknown; content?: unknown }

// What the offload tells the rest of the mod: a result that stays whole and why, and one offloaded.
export type Sink = {
  note: (subject: string, reason: string) => Promise<void>
  offloaded: (plan: OffloadPlan, applied: boolean) => Promise<void>
}

export type Context = { options: OffloadOptions; enforce: boolean; transcriptPath: string | undefined; sink: Sink }

// The first plan whose files do not exist yet: `id`, then `id-2`, `id-3`... Nothing is ever overwritten.
async function freshPlan(
  $: EngineInterface,
  text: string,
  id: string,
  dir: string,
  ctx: Context,
  joined: boolean,
): Promise<OffloadPlan | undefined> {
  for (let n = 1; ; n++) {
    const plan = planOffload(text, n === 1 ? id : `${id}-${n}`, dir, ctx.options, joined)
    if (plan === undefined) return undefined
    let taken = false
    for (const f of plan.files) taken = taken || (await $.fs.exists(f.path))
    if (!taken) return plan
  }
}

// Writes each file whole; the reason of the first failure (4 MiB cap, a refusal, a full disk), else undefined.
async function writeAll($: EngineInterface, plan: OffloadPlan): Promise<string | undefined> {
  try {
    for (const f of plan.files) await $.fs.write(f.path, f.text)
  } catch (error) {
    return String(error).slice(0, 160)
  }
  return undefined
}

// The block the model will read in place of `block`: the pointer, as the string or the text block
// the result came as.
const pointer = <B extends Block>(block: B, message: string): B =>
  typeof block.content === 'string' ? { ...block, content: message } : { ...block, content: [{ type: 'text', text: message }] }

// pre:  `block` is a tool_result whose text is past the threshold (planOffload decides about the
//       engine's own pointers); `dir` is the session's tool-results directory or undefined.
// post: every block gets its own file name (the tool_use id, else `<row uuid>-<block index>`) and an
//       existing file is never overwritten (the next free `-N` suffix is used); the block unchanged (and a note saying why) when the directory is unknown or the write was
//       refused; under observe the block unchanged and nothing written; else the file(s) hold the
//       text whole and the returned block is the pointer. Nothing is ever dropped.
async function offloadOne<B extends Block>(
  $: EngineInterface,
  tool: string,
  block: B,
  text: string,
  dir: string | undefined,
  ctx: Context,
  fallbackId: string,
): Promise<B> {
  const id = typeof block.tool_use_id === 'string' ? block.tool_use_id : fallbackId
  const joined = Array.isArray(block.content) && block.content.length > 1
  const first = planOffload(text, id, dir ?? '', ctx.options, joined)
  if (first === undefined) return block
  if (dir === undefined) {
    await ctx.sink.note('tool-results directory', 'the session directory is not known; the result stays whole')
    return block
  }
  // Under enforce the name is the first free one; under observe nothing is written, so the plan stands.
  let plan = first
  if (ctx.enforce) {
    try {
      plan = (await freshPlan($, text, id, dir, ctx, joined)) ?? first
    } catch (error) {
      await ctx.sink.note(`${tool} result`, `not written, stays whole: ${String(error).slice(0, 160)}`)
      return block
    }
    const failure = await writeAll($, plan)
    if (failure !== undefined) {
      await ctx.sink.note(`${tool} result`, `not written, stays whole: ${failure}`)
      return block
    }
  }
  await ctx.sink.offloaded(plan, ctx.enforce)

  return ctx.enforce ? pointer(block, plan.message) : block
}

// The row's blocks with the long results offloaded; undefined when none changed.
export async function offloadBlocks<B extends Block>(
  $: EngineInterface,
  rowId: string,
  tool: string,
  blocks: readonly B[],
  ctx: Context,
): Promise<B[] | undefined> {
  let dir: string | undefined
  let known = false
  let changed = false
  const out: B[] = []
  for (const [index, block] of blocks.entries()) {
    const text = block.type === 'tool_result' ? resultText(block.content) : undefined
    if (text === undefined || text.length <= ctx.options.thresholdChars) {
      out.push(block)
      continue
    }
    // Asked once, and only when a result is past the threshold: most results never need the directory.
    if (!known) {
      dir = toolResultsDir(ctx.transcriptPath, await $.session.id())
      known = true
    }
    const next = await offloadOne($, tool, block, text, dir, ctx, `${rowId}-${index}`)
    changed = changed || next !== block
    out.push(next)
  }

  return changed ? out : undefined
}

files.hooks/phases.ts:
// Pure side of the phases: which phase a loop (main or a subagent) is in, read off what it does.
// The owner's list (2026-10-14): planning, analysis, design, verification, test, review, report;
// implementation is added for the steps that write code, which none of the seven names.

import type { AdvisorUse, LoopPhases, Phase, PhaseRun, PhasesState } from '../types'
import { type ShellCommand, shellCommands } from './shell'

export const PHASES: readonly Phase[] = [
  'planning',
  'analysis',
  'design',
  'implementation',
  'verification',
  'test',
  'review',
  'report',
]

// source: ~/.claude/plugins/.../zetetic-team-subagents/commands/zetetic/engineering-loop.md, its
// nine steps; the cycle ledger records these, the view shows the phases (reconcilable both ways).
export const ENGINEERING_LOOP: Record<string, Phase> = {
  check: 'planning',
  recall: 'analysis',
  refine: 'planning',
  investigate: 'analysis',
  implement: 'implementation',
  verify: 'verification',
  benchmark: 'test',
  review: 'review',
  remember: 'report',
}

// When one step does several things, the phase it is in is the furthest along this order.
const RANK: Record<Phase, number> = {
  analysis: 0,
  planning: 1,
  design: 2,
  implementation: 3,
  verification: 4,
  test: 5,
  review: 6,
  report: 7,
}

// An agent type's own phase, from its role (the zetetic agents' descriptions); a type not listed
// is placed by what it does, step by step.
const BY_TYPE: [RegExp, Phase][] = [
  [/(^|:)(Plan|orchestrator|dispatch)$/, 'planning'],
  [/(^|:)(Explore|git-historian|research-scientist|data-scientist|professor)$/, 'analysis'],
  [/(^|:)(architect|ux-designer)$/, 'design'],
  [/(^|:)(test-engineer|experiment-runner)$/, 'test'],
  [/(^|:)(code-reviewer|security-auditor|reviewer-academic|advisor)$/, 'review'],
  [/(^|:)(memory-writer)$/, 'report'],
  [/(^|:)(engineer|frontend-engineer|refactorer|simplifier|dba|devops-engineer|mlops|latex-engineer|paper-writer)$/, 'implementation'],
]

export const typePhase = (type: string): Phase | undefined => BY_TYPE.find(([re]) => re.test(type))?.[1]

const PLANNING_TOOLS = new Set(['EnterPlanMode', 'ExitPlanMode', 'TaskCreate', 'TaskUpdate', 'TodoWrite'])
const READING_TOOLS = new Set(['Read', 'Grep', 'Glob', 'WebFetch', 'WebSearch', 'LSP', 'ToolSearch'])
const WRITING_TOOLS = new Set(['Edit', 'Write', 'NotebookEdit'])
// source: Claude Code tool names; the file reads any model can do. Not READING_TOOLS, which also holds
// web and search tools, and not the analysis phase, which also holds delegations, recalls and skills.
export const FILE_READ_TOOLS = new Set(['Read', 'Grep', 'Glob'])

// The one definition of a mechanical step: it calls tools and every call is a file read.
export const isFileReadStep = (uses: readonly { name: string }[]): boolean => uses.length > 0 && uses.every((u) => FILE_READ_TOOLS.has(u.name))

// Each pattern names a command by its head, the first words of a segment (`a && b`, `a; b`, `a | b`),
// so a word inside an argument (`grep pytest`, `git commit -m "fix tsc"`) names nothing.
// An inline check (`python3 -c '...; assert ...'`) carries its own `;`: read on the whole line.
const ASSERT_RUN = /(^|&&\s*)python3? -c .*\bassert\b/
const TEST_RUN = /^(python3? -m (pytest|unittest)|pytest|(npm|pnpm|yarn|bun) (run )?test|claude plugin test|go test|cargo test|(npx (-y )?)?(jest|vitest)|(sh|bash) \S*(mutation_check|reproduce)\S*)/
const CHECK_RUN = /^((uvx )?ruff\S*|(npx (-y )?(-p typescript )?)?tsc|mypy|pyright|(npx (-y )?)?eslint|claude plugin validate|python3? \S*check_craftsmanship|(sh|bash) \S*check-shared|python3? -m mcp_server\.doctor)\b/
const REVIEW_RUN = /^gh pr (review|diff)\b|^gh pr comment\b.*ZETETIC-REVIEW/
const DELIVER_RUN = /^(git (commit|push|tag)|gh pr (create|merge)|gh issue create)\b/
const READ_RUN = /^(ls|cat|head|tail|sed -n|grep|rg|find|wc|git (log|show|status|blame|diff)|gh (pr|issue) (view|list)|which|pwd|echo)\b/
const NEUTRAL_RUN = /^(cd|export|set|source|true)\b/
const DESIGN_FILE = /(^|\/)(docs\/adr\/|wiki\/|design\/)|ADR-\d|\.(md|tex)$/
const TEST_FILE = /(^|\/)(tests?|tests_py|__tests__)\/|\.(test|spec)\.[a-z]+$|_test\.[a-z]+$/

const SKILLS: [RegExp, Phase][] = [
  [/brainstorm|writing-plans|plan$/, 'planning'],
  [/debugging|understand-codebase|recall|research/, 'analysis'],
  [/design|architecture|adr|wiki-author/, 'design'],
  [/test-driven|testing/, 'test'],
  [/verif|integrity|provenance/, 'verification'],
  [/review/, 'review'],
]

const CORTEX = /^mcp__plugin_hypermnesia-mcp_cortex__/
const ARCH = /^mcp__plugin_ai-architect-mcp-codebase_ai-architect__/
const PRD = /^mcp__plugin_ai-architect-mcp-spec_prd-gen__/

const field = (input: unknown, name: string): string => {
  const v = (input as Record<string, unknown> | null)?.[name]
  return typeof v === 'string' ? v : ''
}

const segmentPhase = (segment: string): Phase | undefined => {
  if (segment === '' || NEUTRAL_RUN.test(segment)) return undefined
  if (REVIEW_RUN.test(segment)) return 'review'
  if (TEST_RUN.test(segment)) return 'test'
  if (CHECK_RUN.test(segment)) return 'verification'
  if (DELIVER_RUN.test(segment)) return 'report'
  return READ_RUN.test(segment) ? 'analysis' : 'implementation'
}

// The first line only (a heredoc's body is data); the furthest phase of its segments.
const bashPhase = (command: string): Phase => {
  const line = command.split('\n')[0] ?? ''
  if (ASSERT_RUN.test(line)) return 'test'
  return line
    .split(/&&|\|\||;|\|/)
    .map((s) => segmentPhase(s.trim().replace(/^([A-Z_]+=\S+\s+)+/, '')))
    .filter((p): p is Phase => p !== undefined)
    .reduce<Phase>((best, p) => (RANK[p] > RANK[best] ? p : best), 'analysis')
}

const mcpPhase = (name: string): Phase | undefined => {
  if (CORTEX.test(name)) {
    if (/__(remember|checkpoint|record_session_end)$/.test(name)) return 'report'
    if (/__wiki_(write|adr)$/.test(name)) return 'design'
    return 'analysis'
  }
  if (PRD.test(name)) return /validate|verification/.test(name) ? 'verification' : 'design'
  if (ARCH.test(name)) return /verif|gates|semantic_diff|validate/.test(name) ? 'verification' : 'analysis'
  return undefined
}

// The phase one tool call puts its loop in; undefined when the call says nothing about it.
export const toolPhase = (name: string, input: unknown): Phase | undefined => {
  if (PLANNING_TOOLS.has(name)) return 'planning'
  if (READING_TOOLS.has(name)) return 'analysis'
  if (WRITING_TOOLS.has(name)) {
    const path = field(input, 'file_path') || field(input, 'notebook_path')
    if (TEST_FILE.test(path)) return 'test'
    return DESIGN_FILE.test(path) ? 'design' : 'implementation'
  }
  if (name === 'Bash') return bashPhase(field(input, 'command'))
  if (name === 'Agent') return typePhase(field(input, 'subagent_type'))
  if (name === 'Skill') return SKILLS.find(([re]) => re.test(field(input, 'skill')))?.[1]
  return mcpPhase(name)
}

// Commands that run the repository, the host or the session's worktrees: orchestration, whatever bashPhase
// calls an unrecognised head. A change to a source file is not made by these.
// source: the orchestrator's own first turn (fetch, worktree add, hygiene register-worktree, mkdir)
const PLUMBING_RUN = /^(git|gh|claude|mkdir|rmdir|sleep|python3? \S*disk_hygiene\S*)\b/

// git verbs that rewrite files of the working tree, which the plumbing above does not otherwise do, behind
// any of git's global options (`-C <dir>`, `-c <k=v>`, `--git-dir`, `--work-tree`).
// source: git's own manuals for apply, am, restore, clean, mv, rm, cherry-pick, revert, merge, pull, rebase,
// reset --hard, stash (bare, push, save, pop, apply, branch; not list or show) and `checkout [<tree-ish>] -- <path>`,
// and git(1) for the global options; the review's probes P3 and N1 (2026-10-16) named the verbs and the options
const GIT_OPTION = String.raw`\s+(?:-C\s+\S+|-c\s+\S+|--(?:git-dir|work-tree|namespace)(?:=|\s+)\S+|-P|--no-pager|--bare)`
const GIT_VERB = String.raw`(?:(?:apply|am|restore|clean|mv|rm|cherry-pick|revert|merge|pull|rebase)(?=\s|$)|reset\s(?:.*\s)?--hard(?=\s|$)|stash(?:$|\s+-|\s+(?:push|save|pop|apply|branch)(?=\s|$))|checkout\b.*\s--(?=\s|$))`
const GIT_CHANGE = new RegExp(String.raw`^git(?:${GIT_OPTION})*\s+${GIT_VERB}`)
// Runs that read or check and write nothing: the repository's own gates (`node --test`, `node <script> --check`),
// jq (it has no in-place mode), and inline Python, unless its code writes (PY_WRITES, read on the quoted text).
const READ_ONLY_RUN = /^(node\b.*\s--(test|check)\b|jq\b)/
const PY_INLINE = /^python3? -c\b/
const PY_WRITES = /\.write(_text|_bytes)?\(|\bopen\([^)]*,\s*['"][wax+]/
// source: own choice, the places a session keeps throwaway output (the null device, the system and session temp dirs)
const SCRATCH = /^(\/dev\/|\/tmp\/|\/private\/tmp\/|\$\{?TMPDIR\b)/
// What stands before a command's own head: an assignment (`CI=1 cmd`), and the shell's reserved words and grouping
// (`if`, `then`, `do`, `{`, `!`...). A loop or case header (`for f in ...`) runs nothing itself.
// source: XCU 2.4 Reserved Words, 2.9.1 Simple Commands (variable assignments before the command name)
const ASSIGNMENT = /^[A-Za-z_]\w*=\S*(\s+|$)/
const RESERVED = /^(!|\{|\}|if|then|else|elif|fi|do|done|while|until|esac|time)(\s+|$)/
const HEADER = /^(for|select|case)\s/

// A simple command's head and arguments, less what stands before the head.
const headed = (bare: string): string => {
  let s = bare
  for (let prev = ''; prev !== s; ) {
    prev = s
    s = s.replace(ASSIGNMENT, '').replace(RESERVED, '')
  }
  return HEADER.test(s) ? '' : s
}

const commandChanges = (c: ShellCommand): boolean => {
  if (c.targets.some((t) => !SCRATCH.test(t))) return true
  const s = headed(c.bare)
  if (s === '') return false
  if (GIT_CHANGE.test(s)) return true
  if (PY_INLINE.test(s)) return PY_WRITES.test(c.raw)
  if (PLUMBING_RUN.test(s) || READ_ONLY_RUN.test(s)) return false
  return segmentPhase(s) === 'implementation'
}

// Work the owner's rule hands to a subagent ("aucune tâche ne tourne en session globale"): a file the main
// loop writes (code or test; a document is design, the orchestrator's own), or a shell command that changes
// things in any of the commands the shell runs (shell.ts; a quoted span, a heredoc body or a comment is none):
// a redirection into a file, a git verb that rewrites the working tree, or the implementation phase of
// bashPhase less the plumbing and the read-only runs above. Reads, checks, tests and delivery are orchestration.
export const isMainImplementation = (name: string, input: unknown): boolean => {
  if (WRITING_TOOLS.has(name)) return toolPhase(name, input) !== 'design'
  if (name !== 'Bash') return false
  return shellCommands(field(input, 'command')).some(commandChanges)
}

// A step's phase: the furthest along of its calls; a step that calls nothing and answers is the
// report. Undefined when nothing in it names a phase (the loop stays where it was).
export const stepPhase = (uses: readonly { name: string; input: unknown }[], answer: string): Phase | undefined => {
  if (uses.length === 0) return answer.trim() === '' ? undefined : 'report'
  return uses
    .map((u) => toolPhase(u.name, u.input))
    .filter((p): p is Phase => p !== undefined)
    .reduce<Phase | undefined>((best, p) => (best === undefined || RANK[p] > RANK[best] ? p : best), undefined)
}

export const LOOPS_CAP = 12 // source: own choice, the running agents and the last few done fit one pane

export const emptyPhases = (): PhasesState => ({ turnId: null, loops: [], advisor: { session: 0, uses: [] } })

// A loop keeps its place in the list; a new one goes last, the oldest finished ones make room.
const withLoop = (s: PhasesState, loop: LoopPhases): PhasesState => {
  if (s.loops.some((l) => l.id === loop.id)) return { ...s, loops: s.loops.map((l) => (l.id === loop.id ? loop : l)) }
  const loops = [...s.loops, loop]
  let excess = loops.length - LOOPS_CAP
  return {
    ...s,
    loops: loops.filter((l) => {
      if (excess <= 0 || l.status !== 'done' || l.id === 'main') return true
      excess -= 1
      return false
    }),
  }
}

// Main's row, reset at each turn: its phases are the turn's.
export const startTurn = (s: PhasesState, turnId: string, model: string, at: number): PhasesState =>
  withLoop({ ...s, turnId }, {
    id: 'main',
    type: 'main',
    description: 'main loop',
    model,
    effort: null,
    phase: null,
    runs: [],
    status: 'running',
    advisorCalls: 0,
    wrote: false,
    updatedAt: at,
  })

// A count the runs carry since a version (`reads`, `escalated`): its sum when every run carries it; a
// run recorded before it was counted leaves the sum absent.
const summed = (runs: readonly PhaseRun[], key: 'reads' | 'escalated'): { reads?: number; escalated?: number } =>
  runs.every((r) => r[key] !== undefined) ? { [key]: runs.reduce((n, r) => n + (r[key] ?? 0), 0) } : {}

// The runs an agent made before its type was known, as one run of the type's phase.
const merged = (runs: readonly PhaseRun[], phase: Phase, at: number): PhaseRun => ({
  phase,
  effort: runs[runs.length - 1]?.effort ?? null,
  steps: runs.reduce((n, r) => n + r.steps, 0),
  errors: runs.reduce((n, r) => n + r.errors, 0),
  since: runs[0]?.since ?? at,
  ...summed(runs, 'reads'),
  ...summed(runs, 'escalated'),
})

// A started subagent's row. Its steps may come in before the spawn answers (the engine runs the
// loop meanwhile): a row they opened is completed here, its runs and status kept.
export const spawned = (
  s: PhasesState,
  a: { id: string; type: string; description: string; model: string; at: number },
): PhasesState => {
  const phase = typePhase(a.type) ?? null
  const before = s.loops.find((l) => l.id === a.id)
  if (before !== undefined)
    return withLoop(s, {
      ...before,
      type: a.type,
      description: a.description,
      phase: phase ?? before.phase,
      runs: phase === null ? before.runs : [merged(before.runs, phase, a.at)],
    })
  return withLoop(s, {
    id: a.id,
    type: a.type,
    description: a.description,
    model: a.model,
    effort: null,
    phase,
    runs: phase === null ? [] : [{ phase, effort: null, steps: 0, errors: 0, since: a.at, reads: 0, escalated: 0 }],
    status: 'running',
    advisorCalls: 0,
    wrote: false,
    updatedAt: a.at,
  })
}

const opened = (st: Step): LoopPhases => ({
  id: st.loopId,
  type: st.loopId === 'main' ? 'main' : 'agent',
  description: st.loopId === 'main' ? 'main loop' : 'subagent',
  model: st.model,
  effort: st.effort,
  phase: null,
  runs: [],
  status: 'running',
  advisorCalls: 0,
  wrote: false,
  updatedAt: st.at,
})

export type Step = {
  loopId: string
  model: string
  effort: string | null
  phase: Phase | undefined
  fileRead: boolean // isFileReadStep of the step's tool calls
  escalated: boolean // the stuck escalation set the effort the step was sent at (PhaseRun.escalated)
  advisorCalls: number
  at: number
}

// A step joins the last run: each count the run carries grows by what the step is; a count the run was
// recorded without stays absent, since its earlier steps were never counted.
const joined = (last: PhaseRun, st: Step): PhaseRun => ({
  ...last,
  steps: last.steps + 1,
  ...(last.reads === undefined ? {} : { reads: last.reads + (st.fileRead ? 1 : 0) }),
  ...(last.escalated === undefined ? {} : { escalated: last.escalated + (st.escalated ? 1 : 0) }),
})

// An agent whose type names a phase stays in it (a reviewer reading files is still reviewing);
// main and an unplaced type move with what each step does.
export const stepped = (s: PhasesState, st: Step): PhasesState => {
  const loop = s.loops.find((l) => l.id === st.loopId) ?? opened(st)
  const fixed = loop.type !== 'main' && typePhase(loop.type) !== undefined
  const phase = fixed ? loop.phase : (st.phase ?? loop.phase)
  const last = loop.runs[loop.runs.length - 1]
  const runs =
    phase === null
      ? loop.runs
      : last !== undefined && last.phase === phase && last.effort === st.effort
        ? [...loop.runs.slice(0, -1), joined(last, st)]
        : [...loop.runs, { phase, effort: st.effort, steps: 1, errors: 0, since: st.at, reads: st.fileRead ? 1 : 0, escalated: st.escalated ? 1 : 0 }]
  const advisor = loop.type === 'main' && st.advisorCalls > 0 ? adviced(s.advisor, s.turnId, loop, st) : s.advisor
  return {
    ...withLoop(s, {
      ...loop,
      model: st.model,
      effort: st.effort,
      phase,
      runs,
      advisorCalls: loop.advisorCalls + st.advisorCalls,
      wrote: loop.wrote || st.phase === 'implementation' || st.phase === 'design' || st.phase === 'test',
      updatedAt: st.at,
    }),
    advisor,
  }
}

export const USES_CAP = 20 // source: own choice, the pane lists the last advisor calls only

// The advisor (a server tool of the main loop) is counted with when it was called: before the
// turn wrote anything, after, or in the step that answered.
const adviced = (a: PhasesState['advisor'], turnId: string | null, loop: LoopPhases, st: Step): PhasesState['advisor'] => {
  const when: AdvisorUse['when'] = st.phase === 'report' ? 'at-completion' : loop.wrote ? 'after-write' : 'before-write'
  const use: AdvisorUse = { at: st.at, turnId, phase: loop.phase, when, calls: st.advisorCalls }
  return { session: a.session + st.advisorCalls, uses: [...a.uses, use].slice(-USES_CAP) }
}

// A tool call of the loop failed or was refused: counted on the run it happened in, the evidence
// the insights mod learns each phase's effort from.
export const erred = (s: PhasesState, loopId: string): PhasesState => {
  const loop = s.loops.find((l) => l.id === loopId)
  const last = loop?.runs[loop.runs.length - 1]
  if (loop === undefined || last === undefined) return s
  return withLoop(s, { ...loop, runs: [...loop.runs.slice(0, -1), { ...last, errors: last.errors + 1 }] })
}

export const finished = (s: PhasesState, loopId: string, at: number): PhasesState => {
  const loop = s.loops.find((l) => l.id === loopId)
  return loop === undefined ? s : withLoop(s, { ...loop, status: 'done', updatedAt: at })
}

