// Pure policy: what the mod would change on a request, a subagent or a tool result.
// Observed (logged) or enforced, the decision is the same function of the same facts.

export type Effort = 'low' | 'medium' | 'high' | 'xhigh' | 'max'
export type Pressure = 'none' | 'quota' | 'context'
export type PolicyMode = 'observe' | 'enforce'

// source: platform.claude.com/docs/en/models/haiku-5-5/overview § How it compares (read
// 2026-10-07), the API's default effort per model: Fable 5.1 `high`, Opus 5.5 `medium`,
// Sonnet 5.5 `high`, Haiku 5.5 `medium`. ~/.claude/reference/model-behavior.md § Effort agrees
// on Fable and Opus (Opus `low`/`medium` strong; Sonnet respects effort strictly).
const DEFAULT_EFFORT: { match: string; effort: Effort }[] = [
  { match: 'fable', effort: 'high' },
  { match: 'opus', effort: 'medium' },
  { match: 'sonnet', effort: 'high' },
  { match: 'haiku', effort: 'medium' },
]
const RANK: Record<Effort, number> = { low: 0, medium: 1, high: 2, xhigh: 3, max: 4 }

const isEffort = (v: unknown): v is Effort => typeof v === 'string' && v in RANK

export const defaultEffort = (model: string): Effort => {
  const m = model.toLowerCase()
  return DEFAULT_EFFORT.find((row) => m.includes(row.match))?.effort ?? 'medium'
}

// The owner's ladder (2026-10-07): the first request of a turn keeps its effort, the tool-loop
// requests after it run at medium; under quota or context pressure the loop runs at low and the
// first request drops to medium at most. `base` is the effort the request classifier chose for
// this turn (classify.ts); it replaces the session setting as the rung the ladder starts from,
// so a `routine` turn runs its whole loop at low and a `critical` one keeps high on its first
// request. Without a base the ladder never raises. `loop` is the tool-loop rung the insights
// calibrated for the phase main is in (calibration.ts); medium without one. It is a ceiling like
// the rest: it never lifts a request above its base.
export const effortFor = (
  model: string,
  index: number,
  current: unknown,
  pressure: Pressure,
  base?: Effort,
  loop: Effort = 'medium',
): Effort | undefined => {
  const have = isEffort(current) ? current : defaultEffort(model)
  const now = base ?? have
  const ceiling: Effort = index === 0 ? (pressure === 'none' ? now : 'medium') : pressure === 'none' ? loop : 'low'
  const target = RANK[ceiling] < RANK[now] ? ceiling : now
  return target === have ? undefined : target
}

// Pressure: the five-hour window past the threshold, else the context past its warn mark.
export const pressureOf = (
  rateLimits: readonly { kind: string; percentUsed: number }[],
  quotaPercent: number,
  contextBand: 'measured' | 'warn' | 'hard' | 'unknown',
): Pressure => {
  const fiveHour = rateLimits.find((r) => r.kind === 'five_hour')
  if (fiveHour !== undefined && fiveHour.percentUsed >= quotaPercent) return 'quota'
  if (contextBand === 'warn' || contextBand === 'hard') return 'context'
  return 'none'
}

// A subagent is not touched by pressure: the model and the effort the orchestrator designed (the call's,
// else the definition's) run as designed, whatever the quota or the context. Quota limits how many
// subagents run at once instead (concurrency.ts).

// Memory offload (offload.ts): a result of these tools past the threshold is written whole to a
// file. Only tools whose output is a stream (not a document); a third-party tool's is not ours.
export const OFFLOAD_TOOLS = new Set(['Bash', 'Grep', 'Glob', 'WebFetch', 'WebSearch'])

// source: the rule of thumb the context breakdown uses, about four characters a token.
export const CHARS_PER_TOKEN = 4

// The effort a request carries now: its own setting, else the model's default.
export const currentEffort = (model: string, current: unknown): Effort =>
  isEffort(current) ? current : defaultEffort(model)

// source: effort-calibration.md task table, "genuinely stuck / surprising result → high".
export const STUCK_ERRORS = 3 // source: own choice, three tool errors in a row is a loop, not a slip
const LADDER: readonly Effort[] = ['low', 'medium', 'high', 'xhigh', 'max']
export const escalate = (effort: Effort): Effort => {
  const i = LADDER.indexOf(effort)
  return i < 0 || i >= LADDER.indexOf('high') ? effort : (LADDER[i + 1] ?? effort)
}

// A tool_result's content as the Messages API spells it: a string, or text blocks (joined here).
export const resultText = (content: unknown): string | undefined => {
  if (typeof content === 'string') return content
  if (!Array.isArray(content)) return undefined
  const texts = content
    .map((b) => b as { type?: string; text?: string })
    .filter((b) => b.type === 'text' && typeof b.text === 'string')
    .map((b) => b.text as string)
  return texts.length === content.length ? texts.join('\n') : undefined
}

// Exact counts, thousands grouped by a space: "119 304" (the design system's data surface).
export const group = (n: number): string =>
  String(Math.trunc(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ')

files.hooks/route.ts:
// Pure model routing across the four families (fable, opus, sonnet, haiku): which model a
// subagent runs on, and whether main drops under quota. Families are matched by substring, so
// an alias (`haiku`) and a full id of any release (4.5, 5.5) resolve the same way.

import { type Definition, pinnedModel } from './agents'
import type { Pressure } from './policy'

// Mirrors the zetetic-genius contract (its types/index.d.ts): a mod never imports across mods,
// so the class names are spelled here and checked where the state is read.
export type TaskClass = 'routine' | 'planned' | 'bugfix' | 'analysis' | 'critical'

// source: ~/.claude/reference/agent-reference/effort-calibration.md § Which model when.
// Haiku: a task fully planned by a more capable model with mechanical execution, bounded
// well-specified research. Sonnet: agile coding, agent planning and execution, efficient
// research. Opus: code review and bug-finding, security, formal verification, deep multi-file
// work. Fable: only when explicitly chosen, never the default upgrade path (twice the Opus rate).
// source: platform.claude.com/docs/en/models/haiku-5-5/whats-new-haiku-5-5 (released
// 2026-10-07): Haiku 5.5 is "built for high-volume, latency-sensitive work such as
// classification, routing, extraction, and subagent tasks", takes the effort parameter with
// adaptive thinking on by default, and has a 1M context window with 128k output (the 200K
// ceiling that kept Haiku 4.5 off open searches no longer applies to it).
export const FAMILIES = ['haiku', 'sonnet', 'opus', 'fable'] as const
export type Family = (typeof FAMILIES)[number]

export const SONNET = 'sonnet'
export const HAIKU = 'haiku'
export const OPUS = 'opus'

export const familyOf = (model: string): Family | undefined => {
  const m = model.toLowerCase()
  return FAMILIES.find((f) => m.includes(f))
}

const MECHANICAL_TYPES = /^(Explore|general-purpose|statusline-setup)$|memory-writer|git-historian/i
const CODING_TYPES =
  /engineer$|refactorer|simplifier|test-engineer|data-scientist|dba|devops|mlops|paper-writer|latex|professor|ux-designer/i
const REVIEW_TYPES = /code-reviewer|security-auditor|architect|advisor|reviewer-academic|^Plan$|dispatch|orchestrator/i

// Classes whose execution is mechanical once the request is read (classify.ts).
const MECHANICAL_CLASSES: readonly TaskClass[] = ['routine', 'planned']

// Why a spawn runs on the model it runs on, as the short code kept in the per-spawn record (spawns.ts
// bounds the store by the size of a record, so the sentence is composed where it is shown, not kept):
//   call        the Agent call's `model` stands
//   definition  the agent file's `model` stands
//   kind        an inheriting type, routed by its kind sharpened by the turn's task class
//   inherit     an inheriting type nothing routes: it runs on the parent's model
//   unread      neither a call model nor a readable definition: nothing was decided
export type RouteReason = 'call' | 'definition' | 'kind' | 'inherit' | 'unread'

// What the router decided for one spawn, and the facts it decided from (SpawnRoute in types/index.d.ts
// adds the agent, the clock and what the engine answered). `model` is the rewrite to send, undefined
// when the call stands as it is; `stands` is the model the spawn runs on without a rewrite.
export type Routed = {
  model: string | undefined
  requested: string | null
  definition: string | null
  stands: string
  reason: RouteReason
}

const byKind = (subagentType: string, parentModel: string, taskClass?: TaskClass): string | undefined => {
  const parent = familyOf(parentModel)
  if (parent === undefined || parent === HAIKU || parent === SONNET) return undefined
  const isMechanical = taskClass !== undefined && MECHANICAL_CLASSES.includes(taskClass)
  if (MECHANICAL_TYPES.test(subagentType)) return isMechanical ? HAIKU : SONNET
  if (CODING_TYPES.test(subagentType)) return taskClass === 'planned' ? HAIKU : SONNET
  if (REVIEW_TYPES.test(subagentType)) return parent === 'fable' ? OPUS : undefined
  return undefined
}

// The model a subagent runs on, in this order: the call's `model`, else its definition's, else the
// parent's. A model the call or the definition chose stands, always: no pressure, quota or context,
// changes it (the owner's rule, 2026-10-15: the quota limits how many subagents run at once, concurrency.ts,
// never how well one runs). An inheriting type, which nobody chose a model for, is routed by its kind
// sharpened by the turn's task class, and otherwise inherits the parent's model, which is what the
// engine does when `model` is left undefined (AgentSpawnInput.model: "undefined lets the agent's own
// model, then the parent's, decide"). `definition` undefined means the file could not be read: with no
// call model either, the effective model is unknown and nothing is routed (the decision row names why).
export const routeAgentModel = (
  subagentType: string,
  call: string | undefined,
  definition: Definition | undefined,
  parentModel: string,
  taskClass?: TaskClass,
): Routed => {
  const defined = definition === undefined ? undefined : pinnedModel(definition)
  const facts = { requested: call ?? null, definition: defined ?? null, stands: call ?? defined ?? `inherit ${parentModel}` }
  if (call === undefined && definition === undefined) return { ...facts, model: undefined, reason: 'unread' }
  if (call !== undefined) return { ...facts, model: undefined, reason: 'call' }
  if (defined !== undefined) return { ...facts, model: undefined, reason: 'definition' }
  const kind = byKind(subagentType, parentModel, taskClass)
  return kind === undefined ? { ...facts, model: undefined, reason: 'inherit' } : { ...facts, model: kind, reason: 'kind' }
}

// The main step's `model` is sent to the Messages API as is, and the API knows full ids only:
// the CLI aliases (`sonnet`) are resolved by Claude Code before a session starts, not here.
// Sending `sonnet` made every main step fail over ("Switched to Opus 5 because sonnet is not
// available", 2026-10-14). The Agent tool's `model` is the alias enum, so subagents keep
// `SONNET`/`HAIKU`/`OPUS` above.
// source: Claude model ids, Sonnet 5.5 = 'claude-sonnet-5-5' (measured 2026-10-14:
// `claude -p --model sonnet` reports modelUsage claude-sonnet-5-5)
export const SONNET_MAIN_ID = 'claude-sonnet-5-5'

// Main thread: a model switch forfeits the prompt cache (the engine's model-change event
// carries `prompt_cache_warm` and `estimated_cache_write_usd` for that reason), so the lever
// is pulled for quota pressure alone, never from a request's class. Owner's rule: heavy → sonnet.
export const mainModelFor = (model: string, pressure: Pressure): string | undefined => {
  const f = familyOf(model)
  return pressure === 'quota' && (f === OPUS || f === 'fable') ? SONNET_MAIN_ID : undefined
}

files.hooks/config.ts:
// Whether the owner's options reach this mod. The engine reads `pluginConfigs[<plugin id>].options` and
// the plugin id of an installed mod is `<name>@<marketplace>`; the bare `<name>` is read only for a mod
// loaded by directory (`<name>@inline`). A bare key beside a marketplace install binds to nothing: the
// mod runs on the manifest defaults and says nothing, so the options in effect are named here.

// source: Claude Code 2.1.300, the plugin option lookup (strings of the binary, read 2026-10-15): the
// ids tried for `x@inline` are `x` then `x@inline`, for any other id the id alone; and a live probe the
// same day, a directory-loaded mod reading a value from `pluginConfigs["name"]` and `["name@inline"]`.
export const SETTINGS_PATH = '~/.claude/settings.json'

export type Unbound = { key: string; ids: string[] }

type Installed = { plugins?: Record<string, { installPath?: string }[] | undefined> }

const trimmed = (path: string): string => path.replace(/\/+$/, '')

// The id this copy of the mod runs under: the installed id whose install folder is the folder the engine
// loaded it from (`$.plugin.root`), else the directory-loaded `<plugin>@inline`. Which copy is running
// matters: the engine reads one key for it, and a copy of the same mod beside it reads another.
export const runningId = (installed: Installed, plugin: string, root: string): string =>
  Object.entries(installed.plugins ?? {}).find(
    ([id, records]) => id.startsWith(`${plugin}@`) && (records ?? []).some((r) => r.installPath !== undefined && trimmed(r.installPath) === trimmed(root)),
  )?.[0] ?? `${plugin}@inline`

// The bare key of `plugin` in settings.json when no copy reads it: this copy is an installed one, its
// marketplace key is absent, and the bare key is there. A directory-loaded copy reads the bare key, and a
// marketplace key beside it wins, so neither is a false alarm.
export const unboundKeys = (settingsText: string, installedText: string | undefined, plugin: string, root: string): Unbound[] => {
  let settings: { pluginConfigs?: Record<string, unknown> }
  let installed: Installed
  try {
    settings = JSON.parse(settingsText) as typeof settings
    installed = installedText === undefined ? {} : (JSON.parse(installedText) as Installed)
  } catch (error) {
    throw new Error(`settings.json or installed_plugins.json is not valid JSON (${error instanceof Error ? error.message : String(error)})`.slice(0, 160))
  }
  const configs = settings.pluginConfigs ?? {}
  if (!(plugin in configs)) return []
  const id = runningId(installed, plugin, root)
  return id.endsWith('@inline') || id in configs ? [] : [{ key: plugin, ids: [id] }]
}

// The one line the toast and the POLICY panel carry.
export const unboundMessage = (u: Unbound, mode: string): string =>
  `settings.json pluginConfigs["${u.key}"] is not read by ${u.ids.join(', ')}: key it "${u.ids[0]}". Running on ${mode} from the manifest defaults`

files.hooks/spawns.ts:
// Where a session's spawn routes are kept in the plugin's $.store (4 MiB of JSON in all): one key per
// session, `spawns:<start time, 13 digits>:<session id>`, written by that session alone, so two
// sessions never race on a key. The time leads the key: sorting the keys is sorting the sessions.

import type { SpawnRoute } from '../types'

export const SPAWNS_PREFIX = 'spawns:'
export const STORE_BYTES = 4 * 1024 * 1024 // source: the plugin $.store limit, 4 MiB of JSON in all (Claude Code 2.1.300, $.store in the mods types)

// Which sessions' keys the next start deletes. The newest KEEP_SESSIONS stay. A session started less than
// LIVE_TTL_MS ago stays too, beyond them, up to HARD_SESSIONS: it may still be running, and deleting its
// key would drop the routes it has already written (review of PR 25, B1). Past HARD_SESSIONS the oldest
// goes whatever its age, so the store stays bounded.
export const KEEP_SESSIONS = 20 // source: own choice, three weeks of daily sessions; the bound below
export const HARD_SESSIONS = 2 * KEEP_SESSIONS // source: own choice, room for as many again that are younger than the TTL
// source: measured 2026-10-15 over the 32 session transcripts on this machine (~/.claude/projects, file birth to last write): longest 57.9 h, p95 25.1 h; seven days is three times the longest
export const LIVE_TTL_MS = 7 * 24 * 60 * 60 * 1000
export const SPAWNS_CAP = 50 // source: bounds $.state size; the full record is in $.store, one key per agent
export const ROUTES_PER_SESSION = 100 // source: own choice, above the 12 loops a pane lists (LOOPS_CAP) many times over and far above what one session starts; the oldest is dropped past it

// Every string a record keeps is clipped, so the size of a record has a ceiling and the store a bound.
export const CLIP = { agentId: 40, type: 64, model: 48 } as const // source: own choice, above the longest id, `plugin:agent` name and model id seen (agent ids ~17 characters, `zetetic-team-subagents:security-auditor` 39, `claude-haiku-4-5-20251001` 25)

export const clip = (text: string, max: number): string => (text.length <= max ? text : text.slice(0, max))

export const clipped = (r: SpawnRoute): SpawnRoute => ({
  ...r,
  agentId: clip(r.agentId, CLIP.agentId),
  type: clip(r.type, CLIP.type),
  requested: r.requested === null ? null : clip(r.requested, CLIP.model),
  definition: r.definition === null ? null : clip(r.definition, CLIP.model),
  decided: clip(r.decided, CLIP.model),
  ran: clip(r.ran, CLIP.model),
})

export const spawnsKey = (startedAt: number, sessionId: string): string =>
  `${SPAWNS_PREFIX}${String(Math.trunc(startedAt)).padStart(13, '0')}:${sessionId}`

const startOf = (key: string): number => Number(key.slice(SPAWNS_PREFIX.length, SPAWNS_PREFIX.length + 13))

// The keys to delete so that, with the key about to be written, the rule above holds. `now` is the
// clock the engine reports (a timestamp, not a wait: nothing here sleeps or schedules).
export const staleSpawnKeys = (keys: readonly string[], now: number, keep = KEEP_SESSIONS, hard = HARD_SESSIONS, ttl = LIVE_TTL_MS): string[] => {
  const ours = keys.filter((k) => k.startsWith(SPAWNS_PREFIX)).sort()
  return ours.filter((k, i) => {
    const newerThanIt = ours.length - 1 - i // sessions that started after this one
    if (newerThanIt >= hard - 1) return true
    const isLive = now - startOf(k) < ttl
    return newerThanIt >= keep - 1 && !isLive
  })
}

files.hooks/concurrency.ts:
// How many subagents may run at once, as a function of the quota. Owner rule, 2026-10-15: the quota
// limits the number of agents and of parallel tasks, never how well one agent runs (route.ts leaves a
// designed model and effort alone under any pressure).

import type { AgentInfo } from 'claude-code'

// What the engine allows at `agent.spawn` (Claude Code 2.1.300, AgentSpawnResult in the mods types, read
// 2026-10-15): a hook returns `{ deny: reason }` and "the model sees the text as the Agent tool's error".
// There is no hold or delay: `next` resolves only once the subagent started, and a hook that waits holds
// the whole Agent call. So the strongest mechanism is the refusal, with a reason the orchestrator can act
// on (wait for a running agent to finish, spawn again).

// source: ~/.claude/reference/agent-reference/dynamic-workflows.md, "Agent tool with 2-5 focused subagents - covers most parallel analysis needs"; fan-out above 5 is gated by a cost review there
export const MAX_PARALLEL_AGENTS = 5

// source: logic. A refusal says "wait for a running agent", which needs one running: with a cap of 1 the first spawn always passes, so the orchestrator is never locked out
export const MIN_PARALLEL_AGENTS = 1

// The max_parallel_agents option as set: a positive whole number, else the default and why. The engine refuses a
// value that is not a number (userConfig type: the hooks module does not load), so what reaches here is a number,
// and 0, a negative or a fraction is no count of agents.
export const maxParallelOption = (value: unknown): { max: number; problem?: string } => {
  if (value === undefined) return { max: MAX_PARALLEL_AGENTS }
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) return { max: value }
  return { max: MAX_PARALLEL_AGENTS, problem: `max_parallel_agents=${JSON.stringify(value)} is not a positive whole number; using ${MAX_PARALLEL_AGENTS}` }
}

// The cap for a five-hour window `usedPercent` full: `max` at an empty window, MIN at `quotaPercent` (the
// quota_pressure_percent option, default 80) and past it, a straight line between, rounded up so a nearly
// empty window still has the full cap:
//   cap(u) = max(MIN, ceil(max - (max - MIN) * u / quotaPercent))
// source: own choice of the simplest monotone function through the two ends above. With max 5 and
// quotaPercent 80: 0-19% -> 5, 20-39% -> 4, 40-59% -> 3, 60-79% -> 2, 80%+ -> 1 (tested at each edge).
// No reading of the window (undefined) leaves the cap at max: the quota is unknown, so it limits nothing.
export const parallelCap = (usedPercent: number | undefined, quotaPercent: number, max = MAX_PARALLEL_AGENTS): number => {
  if (usedPercent === undefined) return Math.max(MIN_PARALLEL_AGENTS, max)
  if (!(quotaPercent > 0) || usedPercent >= quotaPercent) return MIN_PARALLEL_AGENTS
  const share = Math.max(0, usedPercent) / quotaPercent
  return Math.max(MIN_PARALLEL_AGENTS, Math.ceil(max - (max - MIN_PARALLEL_AGENTS) * share))
}

// The five-hour window's use out of the engine's rate limits, undefined without a reading.
export const fiveHourPercent = (rateLimits: readonly { kind: string; percentUsed: number }[]): number | undefined =>
  rateLimits.find((r) => r.kind === 'five_hour')?.percentUsed

// Who is inside the orchestrator's budget: a spawn of the main loop's own Agent call, a fork of main included.
// The refusal says "wait for a running agent to finish, then spawn this one again", which only a caller that can
// wait and call again can act on, and the count is of the agents main started. Outside, neither refused nor
// counted (AgentSpawnInput, Claude Code 2.1.301 mods types):
// - `parentAgentId` set: "absent from main"; the spawn happens inside a subagent's or a teammate's loop and is
//   part of the work of the place its parent already holds. Refusing it locked a chain k deep at cap k.
// - `workflow` set: a script's agent(). "A hook can only refuse it", and the script cannot wait and retry: the
//   refusal is an error inside the run. $.agent.list() does not list a workflow's agents either.
// - `isTeammate`: "goes idle between turns and wakes on a message", so its turn.complete frees nothing.
// A fork of main stays inside: `fork` is an Agent call main made (subagentType `fork`), main can wait, and it
// spends the quota any subagent does. The engine's own forks (compaction, memory) raise no agent.spawn: the
// event is raised for the Agent tool's agents and a workflow's agent() only.
export const inBudget = (e: { parentAgentId?: string; workflow?: unknown; isTeammate?: true }): boolean =>
  e.parentAgentId === undefined && e.workflow === undefined && e.isTeammate !== true

// A spawn is refused when `running` agents already fill the cap.
export const isRefused = (running: number, cap: number): boolean => running >= cap

// The cap as the quota sets it: its value, the window's use, and the band the cap falls across.
const capOf = (cap: number, usedPercent: number | undefined, quotaPercent: number, max: number): string =>
  `${cap} at ${usedPercent === undefined ? 'an unread share' : `${Math.round(usedPercent)}%`} of the five-hour window ` +
  `(the cap falls from ${max} to ${MIN_PARALLEL_AGENTS} as the window fills to ${quotaPercent}%)`

// Two readers, two texts (the engine's declarations: a toast "leaves the transcript and the model untouched", a
// spawn's deny is "the Agent tool's error" the model reads). The refusal below is the model's, with the way out.
// The status after it is the user's, who cannot spawn or wait: the fact, and no instruction.
//
// The reason the orchestrator reads as the Agent tool's error: the counts, the quota, the way out.
export const refusalMessage = (running: number, cap: number, usedPercent: number | undefined, quotaPercent: number, max = MAX_PARALLEL_AGENTS): string =>
  `zetetic-autopilot: ${running} subagent${running === 1 ? ' is' : 's are'} running and the cap is ` +
  `${capOf(cap, usedPercent, quotaPercent, max)}. Wait for a running agent to finish, then spawn this one again.`

// What the user reads (a toast, and the POLICY row): which spawn was refused and the numbers behind it.
export const capStatus = (subagentType: string, running: number, cap: number, usedPercent: number | undefined, quotaPercent: number, max = MAX_PARALLEL_AGENTS): string =>
  `zetetic-autopilot: spawn of ${subagentType} refused, ${running} subagent${running === 1 ? '' : 's'} running, cap ` +
  `${capOf(cap, usedPercent, quotaPercent, max)}`

// Of the agents the autopilot believes are running (spawned, no turn.complete seen), those the engine's own
// list confirms are alive. The list is consulted only on the path that would refuse: an agent that ended
// without a turn.complete this mod saw (killed, dropped by the engine) must not hold a slot for good.
const ALIVE: readonly AgentInfo['status'][] = ['pending', 'running', 'waiting']
export const stillRunning = (believed: readonly string[], listed: readonly Pick<AgentInfo, 'id' | 'status'>[]): string[] =>
  believed.filter((id) => ALIVE.includes(listed.find((a) => a.id === id)?.status ?? 'completed'))

files.hooks/gate.ts:
// The quota's cap on parallel subagents as the engine sees it (concurrency.ts holds the pure rules): who
// runs, who is being admitted, and the refusal. The policy state and the phases rows stay in register.tsx,
// behind a `GateSink`, as offloadrow.ts does for the offload.
import type { EngineInterface } from 'claude-code'

import type { PolicyDecision, PolicyState } from '../types'
import { MAX_PARALLEL_AGENTS, capStatus, fiveHourPercent, isRefused, parallelCap, refusalMessage, stillRunning } from './concurrency'

// What the gate tells the rest of the mod: a cap row, a reading it could not make, an agent the engine
// says is gone.
export type GateSink = {
  decide: (d: PolicyDecision) => Promise<void>
  note: (subject: string, reason: string) => Promise<void>
  gone: (id: string, at: number) => Promise<void>
}

// The subagents running now, by id: added when their spawn answers, removed by their turn.complete. Kept in
// this module's memory and not in $.state, because a hook does not see a state row written by a spawn made in the
// same dispatch: two $.agent.spawn calls one after the other inside one hook did not see each other's row (measured
// live 2026-10-15; the engine's docs say nothing of it). `admitting` counts the spawns the gate let through whose
// answer has not come back, so two raised together cannot both pass a cap of one. Both reset with the session.
const live = new Set<string>()
let admitting = 0

// The most subagents running at once with a free quota (the max_parallel_agents option), set when the mod loads.
let maxParallel = MAX_PARALLEL_AGENTS

export const configureGate = (max: number): void => {
  maxParallel = max
}

export const resetGate = (): void => {
  admitting = 0
  live.clear()
}

export const started = (id: string): void => {
  live.add(id)
}

export const ended = (id: string): void => {
  live.delete(id)
}

export const released = (held: boolean): void => {
  if (held) admitting = Math.max(0, admitting - 1)
}

// The agents the engine's list no longer shows alive leave the set and close their phases rows.
async function confirmRunning($: EngineInterface, running: string[], at: number, sink: GateSink): Promise<string[]> {
  const alive = stillRunning(running, await $.agent.list())
  for (const gone of running.filter((id) => !alive.includes(id))) {
    live.delete(gone)
    await sink.gone(gone, at)
  }
  return [...live]
}

// The quota's limit on parallel subagents (concurrency.ts). `held` is true when the spawn passed and is
// counted until it answers; `deny` is the reason the spawn is refused. The check and the count are one
// synchronous step after the reads, so no other spawn hook sits between them. A failure of the gate
// itself admits the spawn and says so in a row, so a broken reading refuses nothing.
export async function admit(
  $: EngineInterface,
  e: { subagentType: string },
  p: PolicyState,
  sink: GateSink,
): Promise<{ held: boolean; deny?: string }> {
  try {
    // The window as the engine reports it now: the context atom is written by session.measure and was one step
    // behind when a spawn hook read it (measured live 2026-10-15, a measure that came after the batch's first spawn).
    const used = fiveHourPercent((await $.session.usage()).rateLimits)
    const cap = parallelCap(used, p.quotaPercent, maxParallel)
    const at = await $.clock.now()
    let running = [...live]
    if (running.length > 0 && isRefused(running.length + admitting, cap)) {
      // The count is event-based; before refusing, the engine's own list confirms who still runs.
      running = await confirmRunning($, running, at, sink)
    }
    const count = running.length + admitting
    if (!isRefused(count, cap)) {
      admitting += 1
      return { held: true }
    }
    const applied = p.mode === 'enforce'
    // Observe lets it go ahead: it is in flight like any admitted spawn and holds the place it gives back,
    // taken in the same synchronous step as the count.
    if (!applied) admitting += 1
    // The row and the toast are the user's: the fact. The deny is Claude's: the fact and the way out.
    const status = capStatus(e.subagentType, count, cap, used, p.quotaPercent, maxParallel)
    await sink.decide({ at, kind: 'cap', subject: e.subagentType, from: `${count} running`, to: `cap ${cap}`, applied, reason: status })
    if (!applied) return { held: true }
    $.ui.toast(status)
    return { held: false, deny: refusalMessage(count, cap, used, p.quotaPercent, maxParallel) }
  } catch (error) {
    await sink.note('agent cap', `not applied: ${String(error).slice(0, 100)}`)
    return { held: false }
  }
}

files.hooks/paths.ts:
// Where `~/` lands on the machine a mod runs on. Pure: the engine follows `$` only inside the module
// that spells it, so each mod's register file reads the three variables and hands their values here.
//
// This file exists once per mod that expands `~/` (a mod cannot import a file from another mod: the
// engine refuses it, "outside the plugin's folder"), and every copy is byte-identical;
// scripts/check-shared.sh fails when one differs.

export type PathVars = { home: string | undefined; userProfile: string | undefined; configDir: string | undefined }
export type Placed = { path: string } | { reason: string }

const isSet = (value: string | undefined): value is string => value !== undefined && value !== ''
const trimmed = (dir: string): string => dir.replace(/[\\/]+$/, '')

// source: HOME is the home on macOS and Linux, USERPROFILE on Windows (cmd and PowerShell set it,
// not HOME); Node's os.homedir() reads them in that order on each platform. Unset in a sandbox: no
// place, said as such, never `/`.
export const homeOf = (vars: PathVars): Placed =>
  isSet(vars.home) ? { path: trimmed(vars.home) } : isSet(vars.userProfile) ? { path: trimmed(vars.userProfile) } : { reason: 'neither HOME nor USERPROFILE is set' }

// source: CLAUDE_CONFIG_DIR relocates the engine's `~/.claude` (plugins/, reference/, settings.json);
// without it the config directory is `<home>/.claude`.
export const configDirOf = (vars: PathVars): Placed => {
  if (isSet(vars.configDir)) return { path: trimmed(vars.configDir) }
  const home = homeOf(vars)

  return 'path' in home ? { path: `${home.path}/.claude` } : home
}

const CONFIG_PREFIX = '~/.claude'

// A path as the mods spell it: `~/.claude/...` is under the config directory, any other `~/...` under
// the home, anything else is already a place.
export const placePath = (vars: PathVars, path: string): Placed => {
  if (!path.startsWith('~/')) return { path }
  const isConfig = path === CONFIG_PREFIX || path.startsWith(`${CONFIG_PREFIX}/`)
  const base = isConfig ? configDirOf(vars) : homeOf(vars)
  if ('reason' in base) return { reason: `${path} has no place: ${base.reason}` }

  return { path: `${base.path}/${path.slice(isConfig ? CONFIG_PREFIX.length + 1 : 2)}` }
}

