{
  "name": "zetetic-autopilot",
  "version": "0.9.0",
  "description": "Automatic effort and model, and a quota that limits how many agents run, not how well one runs. Every request runs at the effort its grade calls for (zetetic-genius) and the main tool loop steps down the ladder. A subagent runs on the model its Agent call names, else the one its agent definition pins (read from the definition file, since agent.spawn carries only the call's), an inheriting type on the family its kind and the turn's class call for, and keeps its effort on every step: no pressure, quota or context, changes a model or an effort the orchestrator designed. Each spawn's requested, definition and decided model, what ran and a short reason are kept per session. Quota pressure limits concurrency: the cap on subagents running at once falls from max_parallel_agents (5) at an empty five-hour window to 1 at quota_pressure_percent, and a spawn past it is refused with a message the orchestrator reads (wait for a running agent to finish). Only the main loop's own spawns, a fork of main included, are counted and refused: a subagent's nested spawn, a workflow script's agent() and a teammate are not. Main itself drops to sonnet under quota pressure, and doing implementation work in the main loop is warned about (POLICY row, toast), never blocked. A long streaming tool result is written whole to a file in the session's tool-results directory and the model reads a preview and the path (nothing is cut). Owns `phases`: the phase each loop is in (planning, analysis, design, implementation, verification, test, review, report), read off its tool calls or, for an agent, its type; on each run, the steps the stuck escalation raised (counted where each raised step landed, under enforce only); and the advisor calls of main with when they came. The tool loop of a phase the insights calibrated runs at that rung instead of medium (never above the request's grade). Starts in enforce; observe logs the decisions without applying them.",
  "types": "./types/index.d.ts",
  "dependencies": [
    "zetetic-genius"
  ],
  "userConfig": {
    "policy_mode": {
      "type": "string",
      "title": "Policy mode",
      "description": "enforce (default): every effort, model, offload and cap decision is applied as logged in the cockpit's POLICY panel. observe: logged only, nothing applied.",
      "default": "enforce",
      "options": [
        "observe",
        "enforce"
      ]
    },
    "quota_pressure_percent": {
      "type": "number",
      "title": "Quota pressure (% of the five-hour window)",
      "description": "Share of the five-hour window at which only one subagent may run at a time (the cap falls in a straight line from max_parallel_agents at 0% to 1 here); at or past it requests also run at low effort and main drops to sonnet. A subagent's own model and effort are never lowered.",
      "default": 80
    },
    "max_parallel_agents": {
      "type": "number",
      "title": "Parallel subagents with a free quota",
      "description": "The most subagents running at once while the five-hour window is empty. It falls to 1 as the window fills to quota_pressure_percent. A spawn past the cap is refused with a message naming the count, the cap and the quota.",
      "default": 5
    },
    "offload_threshold_chars": {
      "type": "number",
      "title": "Offload threshold (characters)",
      "description": "A Bash, Grep, Glob, WebFetch or WebSearch result longer than this is written whole to a file in the session's tool-results directory; the model reads a preview, the path and the size. Nothing is cut. 30000 is Claude Code's own limit for Bash output.",
      "default": 30000
    },
    "offload_preview_chars": {
      "type": "number",
      "title": "Offload preview (characters)",
      "description": "How much of the start of an offloaded result stays in the context (never more than the threshold). 2000 is the preview Claude Code leaves for a result it saves itself.",
      "default": 2000
    }
  },
  "author": {
    "name": "cdeust"
  }
}

